import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** The date this user's screen shows the sheet as of ('': as it is now). It lives in the URL (`asof`),
 *  so it belongs to this screen alone, and every request about the sheet carries it (api/http). */
export const useAsOf = () => useSearchParam('asof', asString);

/** Set or clear the as-of date. While it is set every figure on the screen is the sheet as it stood
 *  at the end of that date, and every change is refused. */
export function AsOf() {
  const queryClient = useQueryClient();
  const [asOf, setAsOf] = useAsOf();
  const [date, setDate] = useState('');

  // Everything on screen is re-read once the URL carries the new date.
  const show = async (value: string) => {
    await setAsOf(value);
    await queryClient.resetQueries();
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const value = date.trim();
        if (value !== '') void show(value);
      }}
    >
      As of <span data-testid="sheet-asof">{asOf}</span>{' '}
      <input
        type="date"
        data-testid="asof-date"
        value={date}
        onChange={(e) => setDate(e.target.value)}
      />{' '}
      <button type="submit" data-testid="asof-set">
        Show as of
      </button>{' '}
      <button type="button" data-testid="asof-clear" onClick={() => void show('')}>
        Show now
      </button>
    </form>
  );
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` tells a conflict (409) from a refusal. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date the screen shows the sheet as of ('': as it is now), from the URL (`asof`). */
function asOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  try {
    const parsed: unknown = JSON.parse(raw);
    return typeof parsed === 'string' ? parsed : raw;
  } catch {
    return raw;
  }
}

/** While the screen shows the sheet as of a date, every request about it says so: the server answers
 *  a read as the sheet stood then and refuses every change. */
function withAsOf(path: string, live: boolean): string {
  const date = live ? '' : asOf();
  if (date === '' || !path.startsWith('/api/sheets/')) return path;
  return `${path}${path.includes('?') ? '&' : '?'}shown-asof=${encodeURIComponent(date)}`;
}

async function send<T>(path: string, init?: RequestInit, live = false): Promise<T> {
  const res = await fetch(withAsOf(path, live), init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

/** `live`: read the sheet as it is now, even while the screen shows it as of a date. */
export function getJson<T>(path: string, live = false): Promise<T> {
  return send<T>(path, undefined, live);
}

export function postJson<T>(path: string, body: unknown, live = false): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }, live);
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useQuery } from '@tanstack/react-query';
import { SheetBody } from '../../slots/defs/sheetBody';
import { claimsKey, listClaims } from '../claims/api';
import { crewsKey, listCrews } from '../crews/api';
import { listNotes, notesKey } from '../notes/api';
import { listPeople, peopleKey } from '../people/api';
import { roleOf, roleOfKey } from '../settings/api';
import { useSheetId, useUser } from '../session/session';
import { openSheet, sheetKey } from './api';
import { SheetToday } from './SheetToday';
import { AsOf } from './AsOf';

/** The loaded sheet: its id, then everything kept on it (the sheet.body region). It shows once its
 *  people, claims and notes are read too, and the user's role and the crews (which decide who has a row),
 *  so the sheet never shows without the rows it holds. */
export function ActiveSheet() {
  const [user] = useUser();
  const [sheetId] = useSheetId();
  const sheet = useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => openSheet(sheetId, user),
    enabled: sheetId !== '',
  });
  const people = useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => listPeople(sheetId),
    enabled: sheet.isSuccess,
  });
  const claims = useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => listClaims(sheetId),
    enabled: sheet.isSuccess,
  });
  const notes = useQuery({
    queryKey: notesKey(sheetId),
    queryFn: () => listNotes(sheetId),
    enabled: sheet.isSuccess,
  });

  const role = useQuery({
    queryKey: roleOfKey(sheetId, user),
    queryFn: () => roleOf(sheetId, user),
    enabled: sheet.isSuccess,
  });
  const crews = useQuery({
    queryKey: crewsKey(sheetId),
    queryFn: () => listCrews(sheetId),
    enabled: sheet.isSuccess,
  });

  if (sheetId === '') return <p data-testid="home-empty">No sheet loaded.</p>;
  if (sheet.isError) return <p data-testid="sheet-error">The sheet could not be loaded.</p>;
  if (!sheet.data || (!people.data && !people.isError) || (!claims.data && !claims.isError)
    || (!notes.data && !notes.isError) || (!role.data && !role.isError)
    || (!crews.data && !crews.isError)) return <p data-testid="sheet-loading">Loading…</p>;

  return (
    <section>
      <h2>
        Sheet <span data-testid="sheet-current-id">{sheet.data.id}</span>
      </h2>
      <SheetToday key={sheet.data.id} sheet={sheet.data} user={user} />
      <AsOf />
      <SheetBody.Slot sheetId={sheet.data.id} user={user} />
    </section>
  );
}
