export const descendantsKey = (id: string) => [...sheetKey(id), 'descendants'] as const;

/** The ids of the sheet's descendants: its children (the sheets naming it as their parent), theirs, ... */
export function listDescendants(id: string, live = false): Promise<string[]> {
  return getJson<string[]>(`/api/sheets/${encodeURIComponent(id)}/descendants`, live);
}

export const treeKey = (id: string) => [...sheetKey(id), 'tree'] as const;

/** The ids of the sheets of the sheet's tree: its root (the top of its parent chain) first, then the
 *  root's descendants, nearest first; the sheet itself among them. */
export function listTree(id: string): Promise<string[]> {
  return getJson<string[]>(`/api/sheets/${encodeURIComponent(id)}/tree`);
}

/** A clone just made: the sheet cloned and the id it was cloned to. */
export type Clone = { from: string; to: string };

/** Clone the sheet to another id; refused (rejects) for anyone but a steward, and when that sheet was
 *  ever used. */
export function cloneSheet(id: string, by: string, to: string): Promise<Clone> {
  return postJson<Clone>(
    `/api/sheets/${encodeURIComponent(id)}/clone?by=${encodeURIComponent(by)}`,
    { to },
  );
}
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => Promise<void>] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    // Resolves once the URL carries the change.
    return navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
